/** since is the first protocol that has the method; capability is the capability bit the harness checks before sending it. */
export interface MethodSpec {
  readonly name: MethodName
  readonly direction: 'executor-to-harness' | 'harness-to-executor' | 'bidirectional'
  readonly kind: 'request' | 'notification'
  readonly since: ProtocolVersion
  readonly capability: string | null
  readonly idempotentBy: string | null
}

